 */
public function resolveScheduledStartTimeForWeekday(int $isoWeekday): ?string
{
    $map = [
        ['week1', 'time1'], ['week2', 'time2'], ['week3', 'time3'],
        ['week4', 'time4'], ['week5', 'time5'], ['week6', 'time6'],
    ];
    foreach ($map as [$wf, $tf]) {
        if ((int) ($this->{$wf} ?? 0) === $isoWeekday) {
            $t = $this->{$tf} ?? null;
            if (!empty($t)) {
                return (string) $t;
            }
        }
    }
    $primary = $this->time ?? null;
    return !empty($primary) ? (string) $primary : null;
