/** Subject code ↔ display name fallback when StudentClass has no explicit subject string. */
private const DEFAULT_SUBJECT = 'Other';

/** @var array<int,string> cache: student_course_id → preferred subject label for schedules.subject */
private array $subjectCache = [];

/**
 * Prefer the subject string already used by other schedules rows for the same
 * student_course_id (preserves UI conventions like "Chemistry"/"化學"). Fall back
 * to Subject.Subject_Name via StudentClass.SubjectID, then to DEFAULT_SUBJECT.
 */
private function resolveSubject(StudentClass $sc): string
{
    $scid = (int) $sc->ID;
    if (isset($this->subjectCache[$scid])) {
        return $this->subjectCache[$scid];
    }
    $existing = DB::table('schedules')
        ->where('student_course_id', $scid)
        ->whereNotNull('subject')
        ->where('subject', '!=', '')
        ->orderByDesc('id')
        ->value('subject');
    if (is_string($existing) && $existing !== '') {
        return $this->subjectCache[$scid] = $existing;
    }
    $subjectId = (int) ($sc->SubjectID ?? 0);
    if ($subjectId > 0) {
        $name = DB::table('Subject')->where('id', $subjectId)->value('Subject_Name');
        if (is_string($name) && $name !== '') {
            return $this->subjectCache[$scid] = $name;
        }
    }
    return $this->subjectCache[$scid] = self::DEFAULT_SUBJECT;
}

