input.command:
php artisan tinker --execute="
use App\Models\StudentClass;
use App\Models\ClassSession;
use Carbon\Carbon;

\$monthly = StudentClass::where('ScheduleMode','!=','count')
    ->orWhereNull('ScheduleMode')
    ->where(function(\$q){ \$q->where('ScheduleMode','date'); })
    ->limit(5)->get(['ID','StudentID','ScheduleMode','monthly_sessions','settlement_day','Charge','Rate','rate_unit','SessionDuration','Paid']);
echo 'Monthly classes sample:' . PHP_EOL;
foreach (\$monthly as \$c) {
    echo 'ID=' . \$c->ID
        . ' mode=' . (\$c->ScheduleMode ?? 'null')
        . ' monthly_sessions=' . (\$c->monthly_sessions ?? '-')
        . ' Charge=' . (\$c->Charge ?? 0)
        . ' Rate=' . (\$c->Rate ?? 0) . '/' . (\$c->rate_unit ?? '-')
        . ' Paid=' . (\$c->Paid ?? 0)
        . PHP_EOL;
}
\$ids = \$monthly->pluck('ID')->all();
\$ms = Carbon::now()->startOfMonth()->toDateString();
\$me = Carbon::now()->endOfMonth()->toDateString();
\$att = \$ids ? ClassSession::whereIn('StudentClassID', \$ids)
    ->whereBetween('SessionDate', [\$ms, \$me])
    ->whereIn('Status', ['completed','attended','late'])
    ->selectRaw('StudentClassID, COUNT(*) c')
    ->groupBy('StudentClassID')->pluck('c','StudentClassID')->toArray() : [];
echo 'Attended this month: ' . json_encode(\$att) . PHP_EOL;
"

input.old_string:
private function resolveMonthlyFee(StudentClass $class): int
{
    $charge = (float) ($class->Charge ?? 0);
    if ($charge > 0) {
        return (int) round($charge);
    }

    $sessions = max(1, (int) ($class->monthly_sessions ?? 4));
    $unitPrice = $this->resolveUnitPrice($class, $sessions);
    if ($unitPrice > 0) {
        return (int) round($unitPrice * $sessions);
    }

    $pay = (float) ($class->Pay ?? 0);
    if ($pay > 0) {
        return (int) round($pay);
    }

    return 0;
}

input.new_string:
private function resolveMonthlyFee(StudentClass $class): int
{
    // 月結課程的「每月應繳」估算：
    //   1) 若設定了 monthly_sessions 且有 Rate → monthly_sessions × 單堂單價（優先，最直覺）
    //   2) 否則使用 Charge 欄位（當該欄儲存月費時）
    //   3) 最後退而求其次用 Pay
    $monthlySessions = (int) ($class->monthly_sessions ?? 0);
    if ($monthlySessions > 0) {
        $unitPrice = $this->resolveUnitPrice($class, $monthlySessions);
        if ($unitPrice > 0) {
            return (int) round($unitPrice * $monthlySessions);
        }
    }

    $charge = (float) ($class->Charge ?? 0);
    if ($charge > 0) {
        return (int) round($charge);
    }

    $pay = (float) ($class->Pay ?? 0);
    if ($pay > 0) {
        return (int) round($pay);
    }

    return 0;
}
